import{_ as a,c as e,o as l,ah as t}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易経の基礎","description":"易経の基礎，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"易経の基礎","description":"易経の基礎，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"ja/articles/basics/index.md","filePath":"ja/articles/basics/index.md"}'),r={name:"ja/articles/basics/index.md"};function s(p,i,n,c,o,d){return l(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="易経の基礎-簡易" tabindex="-1">易経の基礎（簡易） <a class="header-anchor" href="#易経の基礎-簡易" aria-label="Permalink to “易経の基礎（簡易）”">​</a></h1><ul><li>卦（hexagram）：六本の爻で構成され、上三爻が上卦（上の卦）、下三爻が下卦（下の卦）です。</li><li>爻（line）：静爻は陰（--）／陽（—）。本アプリでは八卦の属性（天／地／雷／風／水／火／山／沢）に合わせた色で表示します。動爻（老陰／老陽）は、老陰に「×」、老陽に「○」を付けて示します。</li><li>上卦／下卦：六十四卦はすべて上下二つの卦（トリグラム）から成り、上卦は外卦（用）、下卦は内卦（体）とも呼ばれます。</li><li>当位（位と陰陽の適合）：下から数えて初・二・三・四・五・上。1/3/5 は陽位、2/4/上は陰位。陽爻が陽位、陰爻が陰位にあると「当位（得位）」、逆は「不当位（不得位）」です。</li><li>本卦／之卦：動爻を反転して之卦（変卦）を得ます。読むときは本卦を「体（現状）」、之卦を「用（傾向／調整）」として捉えます。</li></ul><h3 id="変化の読み方-動爻の本数別" tabindex="-1">変化の読み方（動爻の本数別） <a class="header-anchor" href="#変化の読み方-動爻の本数別" aria-label="Permalink to “変化の読み方（動爻の本数別）”">​</a></h3><ul><li><p>1本：本卦のその爻の爻辞を読む。</p></li><li><p>2本：本卦の2本の爻辞を読む（上の爻を優先）。</p></li><li><p>3本：本卦と之卦の卦辞を合わせて読む（本＝体／之＝用）。</p></li><li><p>4本：之卦の不変の2本の爻辞を読む（下の爻を優先）。</p></li><li><p>5本：之卦の不変の1本の爻辞を読む。</p></li><li><p>6本：之卦の卦辞を読む。乾・坤は「用九」「用六」を参照。</p></li><li><p>収録テキスト：本アプリは卦辞／爻辞／象伝の中英対照を収録し、繁簡切替にも対応します。</p></li></ul>',4)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
